/* Kept separate from daily entry and storage so reports never modify history. */
function analyticsPanel(){
  const a=RitmAnalytics.report(state,month,statsHabit),period=`${dateText(a.from)} — ${dateText(a.to)}`;
  const delta=a.delta===null?'Пока недостаточно данных для сравнения':a.delta===0?'На уровне предыдущей недели':`${a.delta>0?'+':''}${a.delta} п. п. к предыдущей неделе`;
  const rate=a.total.target?Math.round(a.total.complete/a.total.target*100):null;
  return `<section class="analytics-panel" aria-labelledby="analytics-title"><div class="section-title"><div><h2 id="analytics-title">Как меняется ваш ритм</h2><p class="muted">Завершённые недели к выбранному месяцу. Текущая неделя ещё не оценивается.</p></div></div>
    <div class="analytics-overview"><article class="card analytics-score"><div class="card-label">ПОСЛЕДНЯЯ ПОЛНАЯ НЕДЕЛЯ</div><strong>${a.current.target?a.current.percent+'%':'—'}</strong><span>${dateText(a.current.from)} — ${dateText(a.current.to)}</span><p class="analytics-delta ${a.delta>0?'positive':''}">${delta}</p><small>${a.current.complete} из ${a.current.target} запланированных выполнений</small></article>
    <article class="card analytics-trend"><h3>8 недель в перспективе</h3><div class="trend-chart" role="list" aria-label="Выполнение плана за восемь завершённых недель">${a.weeks.map(w=>`<div class="trend-column" role="listitem" aria-label="${dateText(w.from)} — ${dateText(w.to)}: ${w.target?w.percent+' процентов, '+w.complete+' из '+w.target:'нет плана'}"><b>${w.target?w.percent+'%':'—'}</b><div class="trend-track"><i style="height:${w.target?Math.max(w.percent,2):0}%"></i></div><span>${R.parse(w.from).toLocaleDateString('ru',{day:'numeric',month:'numeric'})}</span></div>`).join('')}</div><p class="muted">Дневные и недельные цели учитываются по вашему расписанию.</p></article></div>
    <section class="card analytics-habits"><div class="section-title"><div><h3>Регулярность по привычкам</h3><p class="muted">4 полные недели · ${period}</p></div><span class="analytics-total">${rate===null?'Нет плана':rate+'% в среднем'}</span></div>${a.rows.length?a.rows.map(h=>`<div class="regularity-row"><span class="habit-icon" aria-hidden="true">${esc(h.icon)}</span><div class="regularity-info"><strong>${esc(h.name)}${h.archived?' · архив':''}</strong><small>${h.complete} из ${h.target} по плану</small><div class="regularity-track"><i style="width:${h.percent}%"></i></div></div><b>${h.percent}%</b></div>`).join(''):'<div class="empty compact">Здесь появятся результаты после первой завершённой недели с привычками.</div>'}</section>
    ${a.strong||a.weak?`<div class="analytics-insights">${a.strong?`<article class="insight positive"><span>ПОЛУЧАЕТСЯ РЕГУЛЯРНО</span><h3>${esc(a.strong.name)}</h3><p>${a.strong.complete} из ${a.strong.target} выполнений за четыре недели. Этот темп уже работает для вас.</p></article>`:''}${a.weak?`<article class="insight"><span>МОЖНО СДЕЛАТЬ ПРОЩЕ</span><h3>${esc(a.weak.name)}</h3><p>${a.weak.complete} из ${a.weak.target} выполнений. Попробуйте уменьшить цель или выбрать более удобные дни.</p>${a.weak.archived?'':`<button class="text-button" data-edit="${a.weak.id}">Настроить привычку</button>`}</article>`:''}</div>`:''}
    <p class="muted analytics-method">Учитываются цели, которые действовали в те дни. Дни отдыха и паузы в архиве исключены из плана. Выполнения сверх недельной цели не повышают процент выше 100%.</p></section>`;
}
